var n=`0951-takoyaki`;var a=`world-0951`;var o=`JP`;var t=`east-asia`;var s=4;var r=68;var l={en:`Takoyaki`,ua:`Такоякі`};var d={en:`Takoyaki is a Japan dish made with octopus, green onion, pickled ginger, all-purpose flour. This home-scale recipe assigns measured ingredients to the steps where they are used. Takoyaki are cooked in a round takoyaki pan; okonomiyaki sauce substitutes for the named sauce.`,ua:`Такоякі, страва кухні країни Японія. Основні складники: восьминіг, зелена цибуля, маринований імбир, пшеничне борошно універсальне. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Такоякі готують у спеціальній формі з круглими комірками; соус окономіякі замінює соус такоякі.`};var g=[{en:`Cook the listed ingredients in simmering water for about 25 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 25 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:25,i:[[`octopus`,360,`g`],[`water`,750,`ml`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:10,i:[[`green-onion`,90,`g`],[`pickled-ginger`,55,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`all-purpose-flour`,245,`g`],[`dashi-stock`,380,`ml`],[`chicken-egg`,2,`pcs`]]},{en:`Fill round takoyaki mold wells with batter, add cooked octopus and toppings, then rotate each ball until uniformly browned and set.`,ua:`Наповніть круглі лунки форми тістом, додайте готового восьминога й начинку, обертайте кожну кульку до рівномірної рум’яності й готовності.`,t:[`pan-frying`],m:20,i:[[`canola-oil`,50,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`okonomiyaki-sauce`,100,`g`],[`mayonnaise`,90,`g`],[`aonori`,12,`g`],[`katsuobushi`,25,`g`]]}];var u={slug:n,id:a,country:`JP`,region:t,servings:4,minutes:68,title:l,text:d,steps:g};export{o as country,u as default,a as id,r as minutes,t as region,s as servings,n as slug,g as steps,d as text,l as title};